import{_ as t,o as r,c as a,a5 as u}from"./chunks/framework.DJo0M80U.js";const f=JSON.parse('{"title":"流行UI框架","description":"一：Element 官网地址：http://element cn.eleme.io/ /zh CN 介绍：element ui框架的按钮组件，这款由饿了么前端开源的UI框架，一经面世，就收获大量程序员的芳心。在github 上更是高达29.8k的star早已说明一切。用于开发PC。","frontmatter":{"title":"流行UI框架","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","项目实战"],"description":"一：Element 官网地址：http://element cn.eleme.io/ /zh CN 介绍：element ui框架的按钮组件，这款由饿了么前端开源的UI框架，一经面世，就收获大量程序员的芳心。在github 上更是高达29.8k的star早已说明一切。用于开发PC。","sidebarWeight":69,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/实战/流行UI框架.md"},"headers":[],"relativePath":"posts/Vue系统教程/07-项目实战/流行UI框架.md","filePath":"posts/Vue系统教程/07-项目实战/流行UI框架.md"}'),i={name:"posts/Vue系统教程/07-项目实战/流行UI框架.md"};function o(n,e,s,p,h,l){return r(),a("div",null,[...e[0]||(e[0]=[u('<div><h1 id="流行ui框架" tabindex="-1">流行UI框架 <a class="header-anchor" href="#流行ui框架" aria-label="Permalink to &quot;流行UI框架&quot;">​</a></h1><blockquote><p>本节目标：理解“流行UI框架”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><blockquote><p>说明：原 OneNote 中有图片引用，但图片未包含在导出目录中；本页保留了可用的文字与代码内容。 一：Element 官网地址：<a href="http://element-cn.eleme.io/#/zh-CN" target="_blank" rel="noreferrer">http://element-cn.eleme.io/#/zh-CN</a> 介绍：element ui框架的按钮组件，这款由饿了么前端开源的UI框架，一经面世，就收获大量程序员的芳心。在github 上更是高达29.8k的star早已说明一切。用于开发PC端的页面还是绰绰有余的。如果说你是用vue开发者，却没用过element UI，那你肯定不是合格的vue开发者。</p></blockquote><p>二：iview 官网地址：<a href="https://www.iviewui.com/" target="_blank" rel="noreferrer">https://www.iviewui.com/</a> 介绍：iView 是一套基于 Vue.js 的开源 UI 组件库，主要服务于 PC 界面的中后台产品。使用单文件的 Vue 组件化开发模式 基于 npm + webpack + babel 开发，支持 ES2015 高质量、功能丰富 友好的 API ，自由灵活地使用空间，由TalkingData开发维护，有很多知名互联网企业都在使用。</p><p>三：vuetify 官网地址：<a href="https://vuetifyjs.com/zh-Hans/" target="_blank" rel="noreferrer">https://vuetifyjs.com/zh-Hans/</a> 介绍：<a href="https://www.oschina.net/p/vuetify" target="_blank" rel="noreferrer">Vuetifyjs</a> 根据材料设计规格提供 UI 布局。 V 1.0 Alpha 版本提供了超过 80个 reusbale 组件，其中包含一个易于记忆的语义设计，它基于名称简单明了 type-as-you 的类型属性。在GitHub 上有超过 7K 的 star。</p><p>四：vue-strap 官网地址：<a href="http://yuche.github.io/vue-strap/" target="_blank" rel="noreferrer">http://yuche.github.io/vue-strap/</a> 介绍：基于 Vue.js 的 Bootstrap 组件 该仓库包含一系列基于 Bootstrap 标记和 CSS 的本地 Vue.js 组件。所以不需要 jQuery 和 Bootstrap 的 JavaScript 文件，唯一需要依赖的是: Vue.js Bootstrap CSS ，VueStrap 不依赖某个非常精确的 Bootstrap 版本。如果喜欢bootstrap的小伙伴又不想换jquery的开发方式是不二的选择。</p><p>五：cube-ui 官网地址：<a href="https://didi.github.io/cube-ui/#/zh-CN/example" target="_blank" rel="noreferrer">https://didi.github.io/cube-ui/#/zh-CN/example</a> 介绍：cube-ui 是滴滴团队开发的基于 Vue.js 实现的精致移动端组件库。支持按需引入和后编译，轻量灵活；扩展性强，可以方便地基于现有组件实现二次开发。</p><p>六：buefy 官网地址：<a href="https://buefy.github.io/#/" target="_blank" rel="noreferrer">https://buefy.github.io/#/</a> 介绍：Buefy 基于 Bulma 和 Vue.js 的轻量级UI组件，它提供了即装即用的轻量级组件。虽然组件选择有限，但是值得你去尝试。</p><p>七：vue-beauty 官网地址： <a href="https://fe-driver.github.io/vue-beauty/#/components/button" target="_blank" rel="noreferrer">https://fe-driver.github.io/vue-beauty/#/components/button</a> 介绍：基于 ant design 的漂亮的 vue 组件库；vue-beauty 是一套基于 vue.js 和 ant-design样式 的PC端 UI 组件库，旨在帮助开发者提升产品体验和开发效率、降低维护成本。</p><p>八：at-ui 官网地址： <a href="https://at-ui.github.io/at-ui/#/zh" target="_blank" rel="noreferrer">https://at-ui.github.io/at-ui/#/zh</a> 介绍：AT-UI 是一个模块化的前端 UI 框架，开发基于Vue.js 的快速和强大的 Web 界面。专门为桌面应用程序构建，<a href="https://github.com/at-ui/at-ui" target="_blank" rel="noreferrer">AT-UI</a>提供了一套 npm + webpack + babel 前端开发工作流程。全英文的文档对用户来说可能是具有有挑战性的，但它提供了一个体面的干净整洁的 UI 组件。</p><p>九：Vue-Blu 官网地址： <a href="https://chenz24.github.io/vue-blu/#/" target="_blank" rel="noreferrer">https://chenz24.github.io/vue-blu/#/</a> 介绍：Vue-Blu是基于<a href="http://www.vuejs.org/" target="_blank" rel="noreferrer">Vuejs</a>和<a href="http://bulma.io/" target="_blank" rel="noreferrer">Bulma</a>开发的开源UI组件库。旨在为PC端的前端开发(特别是中后台产品)提供一个快速且灵活的解决方案。全面、灵活且强大的ui组件，API友好。</p></div>',1)])])}const c=t(i,[["render",o]]);export{f as __pageData,c as default};
